# Turns the outputs of ipip300_sex_age.py and wvs7_country.py into src/rules/data/personality.ts and src/rules/data/wvs7.ts.
#   python3 docs/data/build_tables.py ipip300_sex_age.json wvs7_country.json src/rules/data
import sys, json
a = json.load(open(sys.argv[1])); d = json.load(open(sys.argv[2])); out = sys.argv[3]
sx = a['female_minus_male_sd']
sexd = [sx['E'], sx['A'], sx['C'], -sx['N'], sx['I']]
bands = a['by_age']; keys = list(bands)
mid = [21, 29.5, 39.5, 49.5, 59.5, 70]; widths = [7, 10, 10, 10, 10, 10]
cols = ['E', 'A', 'C', 'N', 'I']
ref = [sum(bands[k][c] * w for k, w in zip(keys, widths)) / sum(widths) for c in cols]
rows = []
for k, m in zip(keys, mid):
    v = [round(bands[k][c] - r, 3) for c, r in zip(cols, ref)]; v[3] = round(-v[3], 3)
    rows.append(f"[{m}, {', '.join(map(str, v))}]")
ns = [bands[k]['n'] for k in keys]
open(f'{out}/personality.ts', 'w').write(f"""// Generated by docs/data/ipip300_sex_age.py and docs/data/build_tables.py from the IPIP-NEO-300 answers (Johnson 2014 data, as
// uploaded: IPIP300-SCORES.csv, {a['n']:,} adults aged 18–90 who answered every item); do not edit by hand. Item keys come from the sign
// of each item's correlation with its facet score (the file's facet scores are percentiles normed within sex and age, so they rise
// with the raw score inside each group but hide the differences between groups). Domains are the keyed sums of their 60 items, as
// SD of all respondents; intellect is the NEO intellect facet (10 items), the closest to Goldberg's factor V. Order: extraversion,
// agreeableness, conscientiousness, emotional stability (= − neuroticism), intellect.
/** Women minus men, SD. */
export const SEX_D = [{', '.join(str(round(x, 3)) for x in sexd)}];
/** Mean by age band, within each sex and then averaged over the two, against the mean of the six bands weighted by their width
 *  (18–24 counts 7 years, the others 10): [age at the band's middle, the five factors]. Respondents per band: {', '.join(map(str, ns))}. */
export const AGE_TRAITS: number[][] = [{', '.join(rows)}];
""")
names = {'AND':'Andorra','ARG':'Argentina','ARM':'Armenia','AUS':'Australia','BGD':'Bangladesh','BOL':'Bolivia','BRA':'Brazil','CAN':'Canada','CHL':'Chile','CHN':'China','COL':'Colombia','CYP':'Cyprus','CZE':'Czech Republic','DEU':'Germany','ECU':'Ecuador','EGY':'Egypt','ETH':'Ethiopia','GBR':'United Kingdom','GRC':'Greece','GTM':'Guatemala','HKG':'Hong Kong','IDN':'Indonesia','IND':'India','IRN':'Iran','IRQ':'Iraq','JOR':'Jordan','JPN':'Japan','KAZ':'Kazakhstan','KEN':'Kenya','KGZ':'Kyrgyzstan','KOR':'South Korea','LBN':'Lebanon','LBY':'Libya','MAC':'Macau','MAR':'Morocco','MDV':'Maldives','MEX':'Mexico','MMR':'Myanmar','MNG':'Mongolia','MYS':'Malaysia','NGA':'Nigeria','NIC':'Nicaragua','NIR':'Northern Ireland','NLD':'Netherlands','NZL':'New Zealand','PAK':'Pakistan','PER':'Peru','PHL':'Philippines','PRI':'Puerto Rico','ROU':'Romania','RUS':'Russia','SGP':'Singapore','SRB':'Serbia','SVK':'Slovakia','THA':'Thailand','TJK':'Tajikistan','TUN':'Tunisia','TUR':'Turkey','TWN':'Taiwan','UKR':'Ukraine','URY':'Uruguay','USA':'United States','UZB':'Uzbekistan','VEN':'Venezuela','VNM':'Vietnam','ZWE':'Zimbabwe'}
just = ['Q177','Q178','Q179','Q180','Q181','Q182','Q183','Q184','Q185','Q186','Q187','Q188','Q189','Q190','Q191','Q192','Q193','Q194','Q195']
labels = ['claiming government benefits one has no right to', 'avoiding a fare on public transport', 'stealing property', 'cheating on taxes given the chance', "accepting a bribe in the course of one's duties", 'homosexuality', 'prostitution', 'abortion', 'divorce', 'sex before marriage', 'suicide', 'euthanasia', 'a man beating his wife', 'parents beating children', 'violence against other people', 'terrorism for a political, ideological or religious end', 'casual sex', 'political violence', 'the death penalty']
v = lambda x: 'null' if x is None else str(x)
wrows = [f"    '{names[c]}': [{d[c]['year']}, {v(d[c]['trust_most'])}, {v(d[c]['trust_first_meeting'])}, {v(d[c]['religion_important'])}, [{', '.join(v(d[c]['never'][q]) for q in just)}]]," for c in sorted(d, key=lambda x: names[x])]
open(f'{out}/wvs7.ts', 'w').write(f"""// Generated by docs/data/wvs7_country.py and docs/data/build_tables.py from the World Values Survey wave 7 (Haerpfer et al. 2022,
// cross-national file v6.0, 2017–2022, 66 countries and territories), weighted by W_WEIGHT, missing answers left out, a share only
// where 200 or more answered; do not edit by hand. Per country: [main survey year, share saying most people can be trusted (Q57),
// share who trust people they meet for the first time completely or somewhat (Q61), share for whom religion is very or rather
// important in life (Q6), shares calling each act never justifiable (1 on the 1–10 scale, Q177–Q195, in the order of WVS_ACTS)].
export const WVS_ACTS = {json.dumps(labels, ensure_ascii=False)} as const;
export const WVS7: Record<string, [number, number | null, number | null, number | null, (number | null)[]]> = {{
{chr(10).join(wrows)}
}};
""")
print('written')
